appearances.css:
.ws{gap:4px!important;padding:5px!important;font-size:8px}
.top{gap:2px 3px}
.top .lab{font-size:8px}
.top button{font-size:8px;padding:2px 5px;border-radius:3px}
.meter{padding:3px 6px;gap:1px 6px;border-radius:3px;grid-template-columns:auto minmax(60px,1fr) auto}
.meter .lab{font-size:8px}
.meter .big{font-size:13px;min-width:2ch}
.bar{height:6px}
.meter .note{font-size:8px;line-height:1.1}
.map{padding:2px 4px;gap:0;border-radius:3px}
.map canvas{height:60px}
.grid{display:grid!important;grid-template-columns:repeat(9,minmax(0,1fr));gap:4px;align-items:stretch}
.mod{padding:3px 4px 4px;gap:2px 0;border-radius:3px;display:grid!important;grid-template-columns:repeat(var(--n,4),minmax(0,1fr));align-content:start}
.mod h3{grid-column:1/-1;margin:0;padding:0 0 2px;font-size:8px;letter-spacing:.12em;line-height:1.1}
.mod:nth-child(1){--n:5;grid-column:1/6;grid-row:1/3}
.mod:nth-child(3){--n:4;grid-column:6/10;grid-row:1}
.mod:nth-child(5){--n:4;grid-column:6/10;grid-row:2}
.mod:nth-child(2){--n:5;grid-column:1/6;grid-row:3/5}
.mod:nth-child(6){--n:4;grid-column:6/10;grid-row:3/5}
.mod:nth-child(4){--n:5;grid-column:1/6;grid-row:5/7}
.mod:nth-child(7){--n:4;grid-column:6/10;grid-row:5/7}
.k,.k[style]{display:grid!important;align-content:start;grid-template-columns:minmax(0,1fr)!important;justify-items:center;align-items:start;gap:0;min-width:0}
.k label{order:3;font-size:7.5px;letter-spacing:-.03em;text-align:center;max-width:100%;line-height:1.1;white-space:normal;overflow:visible;text-overflow:clip;text-transform:none}
.k output{order:2;font-size:8px;text-align:center;line-height:1.1;color:var(--muted,#8a93a3);white-space:nowrap}
.k .kn{order:1;width:26px!important;height:26px!important;justify-self:center!important}
.k .kn svg{width:100%;height:100%}
.k:has(select){grid-column:span 2}
.k select{order:1;width:100%;font-size:7.5px;padding:3px 0;text-align:center;text-align-last:center;appearance:none;-webkit-appearance:none;border-radius:3px;cursor:pointer}
.k:has(select) label{order:2}
.k:has(input[type=checkbox]){grid-column:span 2}
.k .note{order:1;font-size:7.5px;line-height:1.1;gap:3px!important;justify-content:center}
.keys{gap:1px;overflow:hidden;padding:0}
.keys button{flex:1 1 0;min-width:0;height:34px;font-size:7px;padding:0 0 2px}
.keys button.b{flex:0 0 8px;margin:0 -4px;height:20px}
